<?php
declare(strict_types=1);
session_start();
require __DIR__ . '/config.php';

if (($_GET['action'] ?? '') === 'logout') { session_destroy(); header('Location: admin.php'); exit; }
$loginError='';
if (!admin_logged_in() && $_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='login') {
    if (trim($_POST['username']??'')===RMS_ADMIN_USERNAME && password_verify($_POST['password']??'',RMS_ADMIN_PASSWORD_HASH)) { $_SESSION['admin']=true; $_SESSION['csrf']=bin2hex(random_bytes(24)); header('Location: admin.php'); exit; }
    $loginError='Invalid username or password.';
}
if (!admin_logged_in()) { ?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Holiday Home RMS Login</title><style>body{margin:0;background:#1A1A1A;color:#fff;font-family:Arial;display:grid;place-items:center;min-height:100vh}.box{background:#fff;color:#111;padding:30px;border-radius:16px;width:min(420px,calc(100% - 40px))}h1{font-family:Georgia,serif}.gold{color:#C5A059}.field{margin:14px 0}.field label{display:block;font-size:12px;font-weight:700;margin-bottom:7px}.field input{width:100%;padding:12px;border:1px solid #ddd;border-radius:9px;box-sizing:border-box}.btn{width:100%;padding:13px;border:0;border-radius:9px;background:#C5A059;font-weight:700;cursor:pointer}.err{background:#ffecec;color:#8a2020;padding:10px;border-radius:8px}</style></head><body><div class="box"><div class="gold">HOLIDAY HOME APARTMENTS</div><h1>RMS Admin</h1><?php if($loginError) echo '<div class="err">'.e($loginError).'</div>'; ?><form method="post"><input type="hidden" name="action" value="login"><div class="field"><label>Username</label><input name="username" required></div><div class="field"><label>Password</label><input name="password" type="password" required></div><button class="btn">Sign in</button></form><p style="font-size:12px;color:#666">Development credentials: admin / ChangeMeNow123! Change the password hash in config.php before production.</p></div></body></html>
<?php exit; }

$store=load_store();
if($_SERVER['REQUEST_METHOD']==='POST'){
    check_csrf();$action=$_POST['action']??'';
    with_store_lock(function()use(&$store,$action){
        $store=load_store();
        if($action==='status'){
            $id=(int)$_POST['id'];$status=$_POST['status']??'';$allowed=['pending','confirmed','checked_in','checked_out','cancelled'];
            if(in_array($status,$allowed,true))foreach($store['reservations'] as &$r)if((int)$r['id']===$id){$r['status']=$status;break;}
        } elseif($action==='payment'){
            $id=(int)$_POST['id'];$paid=max(0,(float)($_POST['amount_paid']??0));foreach($store['reservations'] as &$r)if((int)$r['id']===$id){$r['amount_paid']=$paid;break;}
        } elseif($action==='property'){
            $id=(int)($_POST['id']??0);$p=['id'=>$id?:$store['next_property_id']++,'name'=>trim($_POST['name']??''),'location'=>trim($_POST['location']??''),'description'=>trim($_POST['description']??''),'rate'=>(float)($_POST['rate']??0),'rate_period'=>$_POST['rate_period']??'night','bedrooms'=>(int)($_POST['bedrooms']??1),'bathrooms'=>(int)($_POST['bathrooms']??1),'capacity'=>(int)($_POST['capacity']??2),'status'=>$_POST['status']??'active','created_at'=>date('c')];
            $found=false;foreach($store['properties'] as &$row)if((int)$row['id']===$p['id']){$row=array_merge($row,$p);$found=true;break;}if(!$found)$store['properties'][]=$p;
        }
        save_store($store);
    });
    header('Location: admin.php');exit;
}

$store=load_store();$reservations=$store['reservations'];usort($reservations,fn($a,$b)=>strcmp($b['created_at'],$a['created_at']));$properties=$store['properties'];
$active=array_filter($reservations,fn($r)=>$r['status']!=='cancelled');
$totalBookings=count($active);$pending=count(array_filter($reservations,fn($r)=>$r['status']==='pending'));$today=(new DateTime())->format('Y-m-d');$checkin=count(array_filter($reservations,fn($r)=>in_array($r['status'],['pending','confirmed'],true)&&$r['check_in']===$today));$revenue=array_sum(array_map(fn($r)=>(float)$r['total'],$active));
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Holiday Home RMS Admin</title><style>:root{--gold:#C5A059;--ink:#1A1A1A;--line:#e5e7eb;--bg:#f5f5f3}*{box-sizing:border-box}body{margin:0;font-family:Arial,Helvetica,sans-serif;background:var(--bg);color:var(--ink)}header{background:var(--ink);color:#fff;padding:16px 22px;position:sticky;top:0;z-index:5}.nav{max-width:1250px;margin:auto;display:flex;justify-content:space-between;align-items:center}.brand{font-family:Georgia,serif;font-size:20px}.brand span{font-family:Arial;color:var(--gold);font-size:11px;display:block;letter-spacing:2px}.nav a{color:#fff;text-decoration:none}.wrap{max-width:1250px;margin:auto;padding:22px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.stat{background:#fff;border:1px solid var(--line);border-radius:14px;padding:18px}.stat b{font-size:28px;color:var(--gold);display:block}.grid{display:grid;grid-template-columns:2fr 1fr;gap:18px;margin-top:18px}.panel{background:#fff;border:1px solid var(--line);border-radius:14px;padding:18px;overflow:auto}.panel h2{font-family:Georgia,serif;margin-top:0}.table{width:100%;border-collapse:collapse;min-width:900px}.table th,.table td{padding:11px;border-bottom:1px solid var(--line);text-align:left;font-size:13px;vertical-align:top}.badge{padding:5px 8px;border-radius:999px;background:#eee;font-size:11px;font-weight:700}.btn{border:0;border-radius:8px;padding:8px 10px;font-weight:700;cursor:pointer}.gold{background:var(--gold);color:#111}.dark{background:var(--ink);color:#fff}.field{margin:10px 0}.field label{display:block;font-size:11px;font-weight:700;text-transform:uppercase;margin-bottom:6px}.field input,.field select,.field textarea{width:100%;padding:10px;border:1px solid #d7d7d7;border-radius:8px}.two{display:grid;grid-template-columns:1fr 1fr;gap:10px}.notice{font-size:12px;color:#666}@media(max-width:900px){.stats{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}}@media(max-width:600px){.stats{grid-template-columns:1fr}.wrap{padding:14px}.two{grid-template-columns:1fr}}</style></head><body>
<header><div class="nav"><div class="brand">Holiday Home <span>RESERVATION MANAGEMENT SYSTEM</span></div><div><a href="index.php">Booking page</a> &nbsp; · &nbsp; <a href="?action=logout">Logout</a></div></div></header>
<div class="wrap"><div class="stats"><div class="stat">Reservations<b><?=$totalBookings?></b></div><div class="stat">Pending<b><?=$pending?></b></div><div class="stat">Today's check-ins<b><?=$checkin?></b></div><div class="stat">Booked value<b>$<?=number_format($revenue,0)?></b></div></div>
<div class="grid"><div class="panel"><h2>Reservations</h2><table class="table"><thead><tr><th>Reference</th><th>Guest</th><th>Apartment</th><th>Stay</th><th>Total</th><th>Paid</th><th>Status</th><th>Actions</th></tr></thead><tbody>
<?php foreach($reservations as $r): $p=find_property($store,(int)$r['property_id']); ?><tr><td><strong><?=e($r['reference'])?></strong><br><span class="notice"><?=e($r['guest_phone'])?></span></td><td><?=e($r['guest_name'])?><br><span class="notice"><?=e($r['guest_email'])?></span></td><td><?=e($p['name']??'Apartment')?><br><span class="notice"><?=e($p['location']??'')?></span></td><td><?=e($r['check_in'])?><br>→ <?=e($r['check_out'])?><br><span class="notice">Nights: <?=$r['nights']?></span></td><td>$<?=number_format((float)$r['total'],0)?></td><td>$<?=number_format((float)$r['amount_paid'],0)?><br><span class="notice">Bal: $<?=number_format((float)$r['total']-(float)$r['amount_paid'],0)?></span></td><td><span class="badge"><?=e(str_replace('_',' ',$r['status']))?></span></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status" onchange="this.form.submit()"><option value="<?=$r['status']?>"><?=$r['status']?></option><option value="confirmed">confirmed</option><option value="checked_in">checked_in</option><option value="checked_out">checked_out</option><option value="cancelled">cancelled</option><option value="pending">pending</option></select></form><form method="post" style="margin-top:6px"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="payment"><input type="hidden" name="id" value="<?=$r['id']?>"><input name="amount_paid" type="number" step="0.01" value="<?=$r['amount_paid']?>" style="width:90px"><button class="btn gold" type="submit">Save paid</button></form></td></tr><?php endforeach; ?>
