lue="property"><div class="field"><label>Name</label><input name="name" required></div><div class="field"><label>Location</label><input name="location" required></div><div class="two"><div class="field"><label>Rate</label><input name="rate" type="number" step="0.01" required></div><div class="field"><label>Period</label><select name="rate_period"><option value="night">night</option><option value="month">month</option></select></div><div class="field"><label>Bedrooms</label><input name="bedrooms" type="number" value="1"></div><div class="field"><label>Bathrooms</label><input name="bathrooms" type="number" value="1"></div><div class="field"><label>Capacity</label><input name="capacity" type="number" value="2"></div><div class="field"><label>Status</label><select name="status"><option value="active">active</option><option value="inactive">inactive</option></select></div></div><div class="field"><label>Description</label><textarea name="description" rows="3"></textarea></div><button class="btn gold">Add apartment</button></form></div></div></div></body></html>
